package net.civeira.phylax.features.document.template.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.theme.domain.ThemeReference;

class ThemeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property theme of template ")
  void test_theme_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", ThemeVO.fromReference("10").getThemeUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("11", ThemeVO.tryFromReference("11").getThemeUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("12", ThemeVO.tryFromReference("12", fails).getThemeUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertFalse(ThemeVO.nullValue().getTheme().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ThemeVO.tryFrom(null).getTheme().isPresent(),
        "With a null value, no present result");
    Assertions.assertFalse(ThemeVO.fromReference(null).getTheme().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ThemeReference.of("one"),
        ThemeVO.from(ThemeReference.of("one")).getTheme().orElse(null));
    Assertions.assertThrows(ConstraintException.class, () -> ThemeVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ThemeReference.of("one") + "]",
        ThemeVO.from(ThemeReference.of("one")).toString());
  }
}
